const settle=(max)=>{let last=-1,st=0;for(let i=0;i<max;i++){g.renderOnce(1/60);const a=g.lightProbe().adaptation;const e=a?a.autoGain:0;if(i>150&&Math.abs(e-last)<2e-3){if(++st>20)return i;}else st=0;last=e;}return max;};
