const fs=g.rig.fixtures.filter(f=>f.type==='pendant'&&f.tube&&f.level>=0.5&&zf.has(f));
if(!fs.length) throw new Error('no pendant');
const V=g.player.position.constructor; const EYE=1.63;
let done=null;
for(const f of fs){
  const p=f.group.position, m=f.tube.matrix.elements; const t={x:m[12],y:m[13],z:m[14]};
  for(const a of [0,Math.PI/2,Math.PI,-Math.PI/2,Math.PI/4,-Math.PI/4]){
    const px=p.x+Math.sin(a)*Math.min(2.5,3), pz=p.z+Math.cos(a)*Math.min(2.5,3);
