    const dy=t.y-(fl.y+EYE); if(Math.abs(dy)>=2.5*0.94) continue;
    const leg=Math.sqrt(2.5*2.5-dy*dy);
    const ox=p.x+Math.sin(a)*leg, oz=p.z+Math.cos(a)*leg;
    const rc=g.collision.resolveCapsule(ox,fl.y,oz,0.29,1.74); if(!rc||rc.hit||Math.hypot(rc.x-ox,rc.z-oz)>0.05) continue;
