    let yaw=0,pitch=0;
    for(let k=0;k<8;k++){g.look(ox,0,oz,yaw,pitch);g.renderOnce(1/60);
      const v=new V(t.x,t.y,t.z).project(g.engine.camera);
      if(Math.abs(v.x)<0.01&&Math.abs(v.y)<0.01&&v.z<1)break;
      yaw-=v.x*(g.engine.camera.fov*Math.PI/180)*g.engine.camera.aspect*0.5;
      pitch+=v.y*(g.engine.camera.fov*Math.PI/180)*0.5; pitch=Math.max(-1.3,Math.min(1.3,pitch));}
    done={ox,oz,yaw,pitch,t}; break;
  }
  if(done) break;
}
if(!done) throw new Error('no standing point');
g.look(done.ox,0,done.oz,done.yaw,done.pitch);
const fr=settle(400);
console.log('PEND '+JSON.stringify({zone:'residence',range:2.5,stand:[+done.ox.toFixed(2),+done.oz.toFixed(2)],tube:[+done.t.x.toFixed(2),+done.t.y.toFixed(2),+done.t.z.toFixed(2)],eye:+g.player.position.y.toFixed(2),probe:g.lightProbe()}));

